10	// setupAmt 准备：现金 1_000_000；A、B 已设置持仓限额并各有一条报价。
11	func setupAmt(t *testing.T) *Engine {
12		t.Helper()
13		e, _ := NewEngine(1_000_000)
14		mustSetMax(t, e, "A", 1_000)
15		mustSetMax(t, e, "B", 1_000)
16		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
17		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
18		return e
19	}
