21	func TestAmountLimitDisabledByDefault(t *testing.T) {
22		e := setupAmt(t)
23		id := mustBuy(t, e, "A", 5, 10)
24	
25		st := e.PositionAmountStatus()
26		if st.Enabled || st.Limit != 0 || st.Holding != 0 || st.BuyReserved != 0 || st.Total != 0 {
27			t.Fatalf("未设置上限时查询除 Enabled 外必须为零: %+v", st)
28		}
29	
30		// 未设置时不改变基线行为：报价涨到天价也不撤单。
31		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 1_000_000}, 1)
32		if o, _ := e.Order(id); o.Status != StatusPending {
33			t.Fatalf("未设置金额上限时报价不得撤单: %+v", o)
34		}
35		for _, r := range e.Records() {
36			if r.AmtEnabled {
37				t.Fatalf("未设置时记录不得携带金额快照: %+v", r)
38			}
39		}
40	}
