111	func TestAmountNewBuyUsesMaxOfLimitAndQuote(t *testing.T) {
112		e := setupAmt(t)
113		if _, err := e.SetPositionAmountLimit(100); err != nil {
114			t.Fatal(err)
115		}
116	
117		// A 报价 10：买单限价 12 → 每股按 12 占用。5 股 = 60。
118		mustBuy(t, e, "A", 5, 12)
119		if st := e.PositionAmountStatus(); st.Holding != 0 || st.BuyReserved != 60 || st.Total != 60 {
120			t.Fatalf("买单应按限价 12 占用: %+v", st)
121		}
122	
123		// B 报价 20：买单限价 5 → 每股按报价 20 占用。2 股 = 40；合计恰 100，允许。
124		mustBuy(t, e, "B", 2, 5)
125		if st := e.PositionAmountStatus(); st.BuyReserved != 100 || st.Total != 100 {
126			t.Fatalf("合计恰好等于上限应接受: %+v", st)
127		}
128	
129		// 再买任意 1 股都超限（A 最少占用 10，B 最少占用 20）。
130		recsBefore := len(e.Records())
131		if _, err := e.Buy("A", 1, 1); err == nil {
132			t.Fatal("合计超过上限必须拒绝")
133		}
134		rj := e.Records()[recsBefore]
135		if rj.Kind != RecordRejected || rj.AmtLimit != 100 || rj.AmtHolding != 0 ||
136			rj.AmtBuyReserved != 100 || rj.AmtTotal != 100 || rj.AmtApplyTotal != 110 || !rj.AmtEnabled {
137			t.Fatalf("拒绝记录金额快照错误: %+v", rj)
138		}
139		if len(rj.AmtQuoteRefs) != 2 {
140			t.Fatalf("应保存 A、B 两个参与计算合约的报价: %+v", rj.AmtQuoteRefs)
141		}
142	}
