226	func TestAmountSellOrderHoldingStillCountsUntilFill(t *testing.T) {
227		e := setupAmt(t)
228		if _, err := e.SetPositionAmountLimit(100); err != nil {
229			t.Fatal(err)
230		}
231		id := mustBuy(t, e, "A", 10, 10)
232		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
233			t.Fatal(err)
234		}
235		// 持仓 100 已达上限：新买单被拒。
236		if _, err := e.Buy("A", 1, 1); err == nil {
237			t.Fatal("持仓已达上限必须拒绝新买单")
238		}
239	
240		// 挂卖单不提前抵减额度：卖单占用的 6 股仍计入持仓金额。
241		sid := mustSell(t, e, "A", 6, 10)
242		if st := e.PositionAmountStatus(); st.Holding != 100 || st.Total != 100 {
243			t.Fatalf("未成交卖单不得提前抵减额度: %+v", st)
244		}
245		if _, err := e.Buy("A", 1, 1); err == nil {
246			t.Fatal("卖单未成交前额度不得释放")
247		}
248	
249		// 卖出成交后才减少持仓金额（10-6=4 股 × 10 = 40），释放 60 额度。
250		if _, err := e.Fill(Trade{TradeID: 2, OrderID: sid, Symbol: "A", Side: Sell, Price: 10, Qty: 6}); err != nil {
251			t.Fatal(err)
252		}
253		if st := e.PositionAmountStatus(); st.Holding != 40 || st.BuyReserved != 0 || st.Total != 40 {
254			t.Fatalf("卖出成交后应按实际持仓计金额: %+v", st)
255		}
256	}
