312	func TestAmountQuoteRecoveryAllowsBuyAgainNoOrderRestore(t *testing.T) {
313		e := setupAmt(t)
314		if _, err := e.SetPositionAmountLimit(100); err != nil {
315			t.Fatal(err)
316		}
317		b := mustBuy(t, e, "A", 10, 10) // 占用 100
318		// 报价涨到 20：占用 200 超限，撤单。
319		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 20}, 1)
320		if o, _ := e.Order(b); o.Status != StatusCanceled {
321			t.Fatalf("应收敛撤单: %+v", o)
322		}
323		cancelRecs := len(e.Records())
324	
325		// 报价回落：不恢复已撤订单，也不补记录，但可再次买入。
326		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 10}, 1)
327		if o, _ := e.Order(b); o.Status != StatusCanceled {
328			t.Fatal("报价回落不得恢复已撤订单")
329		}
330		if len(e.Records()) != cancelRecs {
331			t.Fatal("报价回落到额度内不得新增记录")
332		}
333		id := mustBuy(t, e, "A", 10, 10)
334		if id == b {
335			t.Fatal("新买单必须使用新订单编号")
336		}
337	
338		// 上调上限同样立即可买。
339		if err := e.Cancel(id); err != nil {
340			t.Fatal(err)
341		}
342		if _, err := e.SetPositionAmountLimit(200); err != nil {
343			t.Fatal(err)
344		}
345		mustBuy(t, e, "A", 15, 10) // 占用 150 ≤ 200
346	}
