func lastAmountRecord(t *testing.T, e *Engine, kind RecordKind) Record {
	t.Helper()
	for i := len(e.records) - 1; i >= 0; i-- {
		if e.records[i].Kind == kind && e.records[i].AmtEnabled {
			return e.records[i]
		}
	}
	t.Fatal("不存在携带金额快照的记录")
	return Record{}
}

