1	package book
2	
3	import (
4		"errors"
5		"math"
6		"strings"
7		"testing"
8	)
9	
10	func mustQuote(t *testing.T, e *Engine, symbol string, q Quote, wantApplied int) {
11		t.Helper()
12		n, err := e.UpdateQuote(symbol, q)
13		if err != nil {
14			t.Fatalf("UpdateQuote(%+v) 意外错误: %v", q, err)
15		}
16		if n != wantApplied {
17			t.Fatalf("UpdateQuote(seq=%d) 生效条数=%d, 期望 %d", q.Seq, n, wantApplied)
18		}
19	}
20	
21	func mustSetMax(t *testing.T, e *Engine, symbol string, max int64) []int64 {
22		t.Helper()
23		ids, err := e.SetMaxPosition(symbol, max)
24		if err != nil {
25			t.Fatalf("SetMaxPosition(%d) 意外错误: %v", max, err)
26		}
27		return ids
28	}
29	
30	func mustBuy(t *testing.T, e *Engine, symbol string, qty, limit int64) int64 {
31		t.Helper()
32		id, err := e.Buy(symbol, qty, limit)
33		if err != nil {
34			t.Fatalf("Buy(%s,%d,%d) 意外错误: %v", symbol, qty, limit, err)
35		}
36		return id
37	}
38	
39	func mustSell(t *testing.T, e *Engine, symbol string, qty, limit int64) int64 {
40		t.Helper()
41		id, err := e.Sell(symbol, qty, limit)
42		if err != nil {
43			t.Fatalf("Sell(%s,%d,%d) 意外错误: %v", symbol, qty, limit, err)
44		}
45		return id
46	}
47	
48	func expectErr(t *testing.T, err error, substr string) {
49		t.Helper()
50		if err == nil {
51			t.Fatalf("期望包含 %q 的错误，实际为 nil", substr)
52		}
53		if !strings.Contains(err.Error(), substr) {
54			t.Fatalf("错误 %q 不包含 %q", err.Error(), substr)
